      const node = queue[index++];
      level.push(node.value);

      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }

    result.push(level);
  }

  return result;
}

function hasCycle(head) {
  let slow = head;
  let fast = head;

  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;

    if (slow === fast) return true;
  }

  return false;
}

function shortestPath(grid) {
  if (!grid.length || grid[0][0] === 1) return -1;

  const rows = grid.length;
  const cols = grid[0].length;
  const queue = [[0, 0, 0]];
  const visited = new Set(['0,0']);
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  for (let index = 0; index < queue.length; index++) {
    const [row, col, distance] = queue[index];
    if (row === rows - 1 && col === cols - 1) return distance;

    for (const [dr, dc] of directions) {
      const nextRow = row + dr;
      const nextCol = col + dc;
      const key = `${nextRow},${nextCol}`;

      if (
        nextRow >= 0 && nextRow < rows &&
        nextCol >= 0 && nextCol < cols &&
        grid[nextRow][nextCol] === 0 &&
        !visited.has(key)
      ) {
        visited.add(key);
        queue.push([nextRow, nextCol, distance + 1]);
      }
    }
  }

  return -1;
}

function hasGraphCycle(graph) {
  const visited = new Set();

  function dfs(node, parent) {
    visited.add(node);

    for (const neighbor of graph[node] || []) {
      if (!visited.has(neighbor)) {
        if (dfs(neighbor, node)) return true;
      } else if (neighbor !== parent) {
        return true;
      }
    }

    return false;
  }

  for (const node of Object.keys(graph)) {
    if (!visited.has(node) && dfs(node, null)) {
      return true;
    }
  }

  return false;
}

function topologicalSort(graph) {
  const indegree = {};

  for (const node of Object.keys(graph)) {
    indegree[node] = 0;
  }

  for (const node of Object.keys(graph)) {
    for (const neighbor of graph[node]) {
      if (!(neighbor in indegree)) indegree[neighbor] = 0;
      indegree[neighbor]++;
    }
  }

  const queue = Object.keys(indegree).filter(node => indegree[node] === 0);
  const result = [];

  for (let index = 0; index < queue.length; index++) {
    const node = queue[index];
    result.push(node);

    for (const neighbor of graph[node] || []) {
      indegree[neighbor]--;
      if (indegree[neighbor] === 0) queue.push(neighbor);
    }
  }

  return result.length === Object.keys(indegree).length ? result : [];
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.cache = new Map();
  }

  get(key) {
    if (!this.cache.has(key)) return -1;

    const value = this.cache.get(key);
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  put(key, value) {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }

    this.cache.set(key, value);

    if (this.cache.size > this.capacity) {
      const oldestKey = this.cache.keys().next().value;
      this.cache.delete(oldestKey);
    }
  }
}
